(()=>{let audio,master,on=false,started=false;const reduced=()=>document.querySelector('#calm').checked||matchMedia('(prefers-reduced-motion: reduce)').matches;function sound(){if(!audio){audio=new AudioContext();master=audio.createGain();master.gain.value=.55;master.connect(audio.destination);const hum=audio.createOscillator(),gain=audio.createGain();hum.frequency.value=43;gain.gain.value=.07;hum.connect(gain).connect(master);hum.start()}audio.resume().catch(()=>{document.querySelector('#sound').textContent='TAP TO ENABLE AUDIO'});on=true;document.querySelector('#sound').textContent='SOUND ON'}function tone(freq,duration=.15,volume=.15){if(!on||!audio)return;const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.type='sine';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(freq*.6,t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g).connect(master);o.start();o.stop(t+duration)}function siren(duration=1.2){if(!on||!audio)return;const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(980,t);for(let j=0;j<duration*4;j++){o.frequency.linearRampToValueAtTime(j%2?1050:1750,t+(j+1)*.25)}g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(.24,t+.04);g.gain.setTargetAtTime(.001,t+duration-.18,.07);o.connect(g).connect(master);o.start();o.stop(t+duration+.2)}function startup(){if(!on||!audio)return;const t=audio.currentTime;for(let i=0;i<3;i++){const o=audio.createOscillator(),g=audio.createGain(),f=audio.createBiquadFilter();o.type=i===0?'sawtooth':'sine';o.frequency.setValueAtTime(160+i*100,t);o.frequency.exponentialRampToValueAtTime(1100+i*430,t+2.4);f.type='lowpass';f.frequency.setValueAtTime(350,t);f.frequency.exponentialRampToValueAtTime(4000,t+2.6);g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(.045,t+.4);g.gain.exponentialRampToValueAtTime(.001,t+2.8);o.connect(f).connect(g).connect(master);o.start();o.stop(t+3)}setTimeout(()=>{tone(1320,.12,.12);setTimeout(()=>tone(1760,.3,.1),150)},2400)}function impact(){siren(1.1);if(on&&audio){const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(100,t);o.frequency.exponentialRampToValueAtTime(25,t+1.7);g.gain.setValueAtTime(.45,t);g.gain.exponentialRampToValueAtTime(.001,t+2.1);o.connect(g).connect(master);o.start();o.stop(t+2.2)}noise(.8);setTimeout(startup,850)}function noise(duration=.12){if(!on||!audio)return;let b=audio.createBuffer(1,audio.sampleRate*duration,audio.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);let src=audio.createBufferSource(),filter=audio.createBiquadFilter(),g=audio.createGain();src.buffer=b;filter.type='bandpass';filter.frequency.value=3200;filter.Q.value=3.2;g.gain.value=.18;const now=audio.currentTime;for(let j=0;j<duration*24;j++){g.gain.setValueAtTime(j%2?.001:.18,now+j/24)}src.connect(filter).connect(g).connect(master);src.start()}document.querySelector('#audioTest').onclick=()=>{sound();master.gain.value=.55;siren(.8);setTimeout(startup,950)};document.querySelector('#sound').onclick=()=>{if(!audio||!on)sound();else{on=false;master.gain.value=0;document.querySelector('#sound').textContent='SOUND OFF'}if(on)master.gain.value=.55};document.querySelector('#calm').onchange=()=>document.body.classList.toggle('calm',reduced());document.querySelector('#initialize').onclick=async()=>{if(started)return;started=true;document.querySelector('#initialize').disabled=true;document.body.classList.toggle('calm',reduced());try{sound()}catch{}const log=document.querySelector('#bootLog');for(const line of ['CONNECTING TO MuSyChEN–626 ...','WARNING: STELLAR COLLAPSE IN PROGRESS','CONTAINMENT ALARMS / ACTIVE','ROUTING TO OBSERVATION LAB ...']){log.textContent+=line+'\n';tone(720,.13,.1);await new Promise(r=>setTimeout(r,45))}document.querySelector('#transitionFX').classList.add('active');impact();noise(.15);document.querySelector('#boot').hidden=true;document.body.classList.remove('awaiting-init');document.body.classList.add('emergency','compiling','collapse');window.rebootSequence();document.querySelector('#replay').click();for(let j=0;j<6;j++){setTimeout(()=>{if(j%2===0)siren(.5);noise(.04)},j*180)}setTimeout(async()=>{document.body.classList.remove('emergency');document.querySelector('#transitionFX').classList.remove('active');const output=document.querySelector('#compiledTransmission');const lines=['[BOOT] NEXUS KERNEL 6.26 // LINK ESTABLISHED','[CALC] Δt = t(origin) − t(arrival) // SOLVING','[SCAN] 626 REALITY BRANCHES // MAPPING','[WARNING] CROSS-REALITY IDENTITY COLLISION','[CALC] ψ(convergence) → COORDINATE LOCK','[CONTAINMENT] STELLAR ANOMALY // STABILISED','[ARCHIVE] YOUR ALTERNATE SELF HAS BEEN DETECTED','[PROTOCOL] PRIME AND VARIANT SIGNATURES ACCEPTED','[DATE] 18 DECEMBER 2026 // CONFIRMED','[LOCATION] B-EVOLUTION · TORINO','[ADDRESS] VIA VIRLE 14/C','[TIME] ARRIVAL WINDOW // PENDING','[ACTION] CONFIRM CROSSING · DECLARE IDENTITY'];for(const line of lines){const row=document.createElement('div');row.className=line.includes('WARNING')?'cmd-warning':line.includes('CALC')?'cmd-calc':line.includes('ARCHIVE')?'cmd-lore':line.includes('CONFIRMED')||line.includes('STABILISED')?'cmd-ok':'cmd-info';output.append(row);output.scrollTop=output.scrollHeight;row.textContent=line;tone(1400,.018,.04);row.textContent=line;await new Promise(r=>setTimeout(r,22))}document.body.classList.remove('compiling');document.querySelector('#enter').classList.add('ready');document.querySelector('#terminal').hidden=false},3900)};
const charts=['spectrum','oscilloscope'].map(id=>{const el=document.getElementById(id);el.width=400;el.height=100;return [el.getContext('2d'),id]});const rain=document.querySelector('#matrix'),rg=rain.getContext('2d');function resize(){rain.width=innerWidth;rain.height=innerHeight}resize();addEventListener('resize',resize);let tick=0;function frame(t){requestAnimationFrame(frame);if(tick++%3)return;for(const [g,id]of charts){g.clearRect(0,0,400,100);g.strokeStyle='#13436b';g.lineWidth=1;for(let i=0;i<400;i+=25){g.beginPath();g.moveTo(i,0);g.lineTo(i,100);g.stroke()}g.strokeStyle='#38b8ff';g.shadowColor='#0066ff';g.shadowBlur=8;if(id==='oscilloscope'){g.beginPath();for(let i=0;i<400;i++)g.lineTo(i,50+Math.sin(i*.04+t*.004)*24+Math.sin(i*.15-t*.006)*10);g.stroke()}else for(let i=0;i<40;i++){g.fillStyle=i>33?'#ff4c83':'#147aff';g.fillRect(i*10,100,6,-12-70*Math.abs(Math.sin(i*.5+t*.002)*Math.sin(i*.2-t*.001)))}g.shadowBlur=0}if(!reduced()){rg.clearRect(0,0,rain.width,rain.height);rg.fillStyle='#2485ff';rg.font='10px monospace';for(let j=0;j<18;j++){let x=(j*137)%rain.width,y=(t*.025+j*80)%(rain.height+120)-120;rg.fillText('626 / '+((tick+j*7)%256).toString(16).padStart(2,'0')+' ::',x,y)}}}requestAnimationFrame(frame);const logs=document.querySelector('#liveLogs');const messages=['WARNING / REALITY FRACTURE','NEXUS HANDSHAKE / 626','EJECTA VELOCITY / UNSTABLE','VARIANT SIGNAL / DETECTED','ANCHOR PROTOCOL / HOLD'];setInterval(()=>{document.querySelector('#integrity').textContent=(61+Math.random()*4).toFixed(1)+'%';document.querySelector('#drift').textContent='+'+(.5+Math.random()*.3).toFixed(3)+' ns';const line=document.createElement('div');line.textContent=new Date().toLocaleTimeString('en-GB')+' // '+messages[Math.floor(Math.random()*messages.length)];line.className=line.textContent.includes('WARNING')?'cmd-warning':line.textContent.includes('ANCHOR')?'cmd-calc':'cmd-info';logs.prepend(line);while(logs.children.length>5)logs.lastChild.remove()},650);setInterval(()=>{if(!started)return;if(!reduced())document.body.classList.add('interference');noise(.08);tone(2300,.035,.08);setTimeout(()=>tone(3100,.025,.05),55);setTimeout(()=>document.body.classList.remove('interference'),260);const toast=document.querySelector('#alertToast');toast.textContent=['⚠ DIMENSIONAL INTERFERENCE DETECTED','⚠ STELLAR EJECTA / CONTAINMENT ACTIVE','⚠ CROSS-REALITY SIGNATURE OVERLAP'][Math.floor(Math.random()*3)];toast.classList.add('show');tone(2600,.025,.055);noise(.07);setTimeout(()=>toast.classList.remove('show'),2800)},5500);document.addEventListener('click',e=>{if(started&&e.target.closest('button'))tone(1200,.035,.05)});})();
